SET NAMES utf8mb4;
-- ----------------------------
-- Table data for mac_type
-- ----------------------------
-- ----------------------------
-- 分类名称内容级多语言（默认演示分类的六语译文）
-- ----------------------------
ON DUPLICATE KEY UPDATE data=JSON_SET(COALESCE(data,'{}'),'$.type_name',JSON_UNQUOTE(JSON_EXTRACT(VALUES(data),'$.type_name'))),status=VALUES(status),source=VALUES(source),update_time=VALUES(update_time);
